from __future__ import annotations

import csv
import json
from collections import defaultdict
from datetime import datetime
from pathlib import Path


DATASET_DIR = Path("/app/dataset")
PRODUCT_CATALOG = DATASET_DIR / "product_catalog.csv"
TEMPERATURE_LOGS = DATASET_DIR / "temperature_logs.csv"
WAREHOUSE_DISPATCHES = DATASET_DIR / "warehouse_dispatches.csv"


def _parse_decimal(value: str) -> float:
    return float(str(value).replace(",", "."))


def _normalize_category(value: str) -> str:
    return value.strip().lower().capitalize()


def _load_catalog() -> dict[str, dict[str, float | str]]:
    catalog: dict[str, dict[str, float | str]] = {}
    with PRODUCT_CATALOG.open(newline="") as handle:
        reader = csv.DictReader(handle)
        for row in reader:
            catalog[row["product_id"]] = {
                "storage_category": row["storage_category"],
                "unit_price": _parse_decimal(row["unit_price"]),
                "max_safe_temp_c": _parse_decimal(row["max_safe_temp_c"]),
            }
    return catalog


def _load_dispatches() -> list[dict[str, int | str | datetime]]:
    dispatches: list[dict[str, int | str | datetime]] = []
    with WAREHOUSE_DISPATCHES.open(newline="") as handle:
        reader = csv.DictReader(handle)
        for row in reader:
            dispatches.append(
                {
                    "dispatch_id": int(row["dispatch_id"]),
                    "timestamp": datetime.strptime(row["timestamp"], "%Y-%m-%d %H:%M:%S"),
                    "product_id": row["product_id"],
                    "quantity": int(row["quantity"]),
                }
            )
    return dispatches


def _find_disposal_dispatch_ids(
    catalog: dict[str, dict[str, float | str]],
    dispatches: list[dict[str, int | str | datetime]],
) -> set[int]:
    safe_temp_by_category = {
        _normalize_category(meta["storage_category"]): float(meta["max_safe_temp_c"])
        for meta in catalog.values()
    }

    excursion_categories: set[str] = set()
    incident_start: datetime | None = None
    incident_end: datetime | None = None

    with TEMPERATURE_LOGS.open(newline="") as handle:
        reader = csv.DictReader(handle)
        for row in reader:
            category = _normalize_category(row["zone"])
            safe_temp = safe_temp_by_category.get(category)
            if safe_temp is None:
                continue

            observed_temp = _parse_decimal(row["temperature_c"])
            if observed_temp <= safe_temp:
                continue

            timestamp = datetime.strptime(row["timestamp"], "%Y-%m-%d %H:%M:%S")
            excursion_categories.add(category)
            incident_start = timestamp if incident_start is None else min(incident_start, timestamp)
            incident_end = timestamp if incident_end is None else max(incident_end, timestamp)

    if not excursion_categories or incident_start is None or incident_end is None:
        return set()

    suspect_groups: dict[datetime, list[dict[str, int | str | datetime]]] = defaultdict(list)
    for dispatch in dispatches:
        category = _normalize_category(str(catalog[str(dispatch["product_id"])]["storage_category"]))
        timestamp = dispatch["timestamp"]
        if incident_start <= timestamp <= incident_end and category in excursion_categories:
            suspect_groups[timestamp].append(dispatch)

    if not suspect_groups:
        return set()

    disposal_timestamp, rows = max(suspect_groups.items(), key=lambda item: len(item[1]))

    # Only exclude a batch when it is unmistakable: a multi-line dispatch burst in the
    # affected categories during the exact temperature incident window.
    if len(rows) < 3:
        return set()

    return {int(dispatch["dispatch_id"]) for dispatch in rows}


def answer() -> int:
    catalog = _load_catalog()
    dispatches = _load_dispatches()
    disposal_dispatch_ids = _find_disposal_dispatch_ids(catalog, dispatches)

    revenue = 0.0
    for dispatch in dispatches:
        if int(dispatch["dispatch_id"]) in disposal_dispatch_ids:
            continue

        product = catalog[str(dispatch["product_id"])]
        revenue += int(dispatch["quantity"]) * float(product["unit_price"])

    return int(round(revenue))


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

